template<size_t N>void check(unsigned bits,int phase){Graph g;g.header="<!-- dmx encoding binary 5 format sfm_session 20 -->\n";g.strings={"DmeTransform","test","value","DmeDag","parent","transform"};Element e{};e.type=0;e.name=1;e.id[0]=1;Value v;v.wire.resize(N*4);e.attributes.push_back({2,N==3?uint8_t(10):uint8_t(13),{v}});g.elements.push_back(e);Element parent{};parent.type=3;parent.name=4;parent.id[0]=2;Value ref;ref.reference=0;parent.attributes.push_back({5,1,{ref}});g.elements.push_back(parent);RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(g,[](const std::string&,auto&){return 0xffffffffu;});auto&flags=p.typedAttributeFlags[0][0];flags=uint16_t((N==3?10:13)|((bits&1)?0x20:0)|((bits&2)?0x400:0)|((bits&4)?0x2000:0)|((bits&8)?0x80:0));auto initial=flags;std::array<float,N>incoming{};for(size_t i=0;i<N;++i)incoming[i]=float(i+1);bool expected=attributeMutationPermitted(initial,phase);bool actual=p.setFloatComponents(0,"value",incoming,phase);if(actual!=expected||flags!=(expected?uint16_t(initial|0x4080):initial))throw std::runtime_error("typed gate flags");if(expected){if(std::memcmp(p.graph.elements[0].attributes[0].values[0].wire.data(),incoming.data(),N*4))throw std::runtime_error("payload write");if(p.scene.queues.dirty.handles.size()!=2||p.scene.resolve(p.elementHandles[0])->flags!=1||p.scene.resolve(p.elementHandles[1])->flags!=1||!(p.scene.references.frameworkFlags&0x2000))throw std::runtime_error("owner dirty propagation");auto queued=p.scene.queues.dirty.handles.size();if(p.setFloatComponents(0,"value",incoming,3)||p.scene.queues.dirty.handles.size()!=queued)throw std::runtime_error("equal no-op");}else if(p.graph.elements[0].attributes[0].values[0].wire!=v.wire||!p.scene.queues.dirty.handles.empty())throw std::runtime_error("rejected write side effects");p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(p.setFloatComponents(0,"value",incoming,0))throw std::runtime_error("stale owner write");}
int main(){try{static_assert(sizeof(void*)==8,"x64 required");for(unsigned bits=0;bits<16;++bits)for(int phase=0;phase<8;++phase){check<3>(bits,phase);check<4>(bits,phase);}std::cout<<"owned_vector_quaternion_write_cases=256 gate_payload_owner_reverse_dirty_equal_stale=passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
